def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    blue, gray, red = 1, 5, 2
    out = g.copy()

    # The blue wall's lowest row; recesses are below-wall background cells
    # (connected to the bottom edge) that lie at or above this row.
    bottom = int(np.where(g == blue)[0].max())
    below = set()
    for region in components(g != blue):
        if any(y == H - 1 for y, x in region):
            below.update(region)
    holes = np.zeros(g.shape, bool)
    for y, x in below:
        if y <= bottom:
            holes[y, x] = True
    recesses = [set(c) for c in components(holes)]

    for cells in components(g == gray):
        y0, x0, y1, x1 = bbox(cells)
        mask = np.zeros((y1 - y0 + 1, x1 - x0 + 1), bool)
        for y, x in cells:
            mask[y - y0, x - x0] = True
        witness = None
        for k in range(4):
            rc = [(int(y), int(x)) for y, x in np.argwhere(np.rot90(mask, k))]
            for index, hole in enumerate(recesses):
                hy, hx = min(hole)
                for py, px in rc:
                    dy, dx = hy - py, hx - px
                    placed = {(y + dy, x + dx) for y, x in rc}
                    if not hole <= placed:
                        continue
                    if all(0 <= y < H and 0 <= x < W and g[y, x] != blue for y, x in placed):
                        witness = (index, k)
                        break
                if witness is not None:
                    break
            if witness is not None:
                break
        if witness is not None:
            for y, x in cells:
                out[y, x] = red
            index, k = witness
            emit(out, f'Gray piece at rows {y0}-{y1}, cols {x0}-{x1} can plug recess {index+1} of the blue wall '
                      f'(after a {90*k}-degree rotation) without overlapping blue: paint it red in place.')
        else:
            emit(out, f'Gray piece at rows {y0}-{y1}, cols {x0}-{x1} fits no recess in any rotation: it stays gray.')

    emit(out, 'Done: pieces that can plug a wall recess are red, the rest remain gray, wall unchanged.')
    return out
